using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Demo6.Game;
public static class TextureV7Checks {
 public static object Run(){var rows=new List<object>();void Check(string name,bool pass,object detail=null)=>rows.Add(new{name,pass,detail});
 foreach(string id in new[]{"body_leather","sleeve_leather","short_cape","longsword"}){string old="Assets/Art/TopDown/"+(id=="short_cape"?"PlayerV5/":"PlayerV4/")+id+".png",current="Assets/Art/TextureStudyV7/Hero/"+id+".png";var before=AssetDatabase.LoadAssetAtPath<Sprite>(old);var after=AssetDatabase.LoadAssetAtPath<Sprite>(current);Check(id+"-dimensions-pivot-ppu",before.rect==after.rect&&before.pivot==after.pivot&&before.pixelsPerUnit==after.pixelsPerUnit,new{before=before.rect.ToString(),after=after.rect.ToString(),pivot=after.pivot.ToString(),ppu=after.pixelsPerUnit});var a=new Texture2D(2,2);var b=new Texture2D(2,2);a.LoadImage(File.ReadAllBytes(old));b.LoadImage(File.ReadAllBytes(current));var p=a.GetPixels32();var q=b.GetPixels32();int alpha=0,rgb=0;for(int i=0;i<p.Length;i++){if(p[i].a!=q[i].a)alpha++;if(p[i].a>0&&(p[i].r!=q[i].r||p[i].g!=q[i].g||p[i].b!=q[i].b))rgb++;}Check(id+"-alpha-identical",alpha==0,new{differentAlpha=alpha});Check(id+"-material-edited",rgb>0,new{changedRgbPixels=rgb});UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);}
 var floor=Resources.Load<Sprite>("TextureStudyV7/entry_floor");var wall=Resources.Load<Texture2D>("TextureStudyV7/wall_tile");Check("floor-existing-world-size",floor&&floor.pixelsPerUnit==16&&floor.bounds.size.x==28&&floor.bounds.size.y==16);Check("wall-existing-period-readable",wall&&wall.width==128&&wall.height==128&&wall.isReadable);
 var set=AssetDatabase.LoadAssetAtPath<CombatArtSet>("Assets/Data/Combat/CombatArtSet.asset");Check("player-pilot-bound",set.topDown.player.body.name=="body_leather"&&AssetDatabase.GetAssetPath(set.topDown.player.body).Contains("TextureStudyV7"));Check("cape-pilot-bound",AssetDatabase.GetAssetPath(set.topDown.player.cape).Contains("TextureStudyV7"));Check("other-armors-preserved",set.topDown.player.armors.Where(x=>x.armorId!="arm_leather").All(x=>AssetDatabase.GetAssetPath(x.body).Contains("PlayerV4")));Check("effects-v6-preserved",AssetDatabase.GetAssetPath(set.effects.whirl).Contains("EffectsV6"));
 var result=new{total=rows.Count,failed=rows.Count(x=>!(bool)x.GetType().GetProperty("pass").GetValue(x)),rows};Directory.CreateDirectory("검증/텍스처-시범-v7");File.WriteAllText("검증/텍스처-시범-v7/asset-checks.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}
}
